import {randomUUID} from 'node:crypto';
import type {PoolClient} from 'pg';
import type {CurrentSession} from '../../../lib/server/auth/sessions';
import {submitPlanCommand} from '../../../lib/server/plans/commands';
import {createPlanReviewPreview,decidePlan} from '../../../lib/server/plans/decisions';
import {syntheticPlanContent} from '../plans/seed';
import type {PlanDraftContent} from '../../../lib/contracts/plan-content';
import {requireOwnedGapDatabase} from '../../../scripts/gaps-eval-environment';
export async function gapDeliveryBaseline(db:PoolClient,author:CurrentSession,reviewer:CurrentSession,customerId:string){requireOwnedGapDatabase();const content=syntheticPlanContent() as PlanDraftContent;content.assertions=[];content.sourceDependencies=[];content.asOf=new Date(Date.now()-10000).toISOString();const created=await submitPlanCommand(author,{action:'create',requestKey:randomUUID(),workspaceId:author.workspaceId,customerId,workloadId:null,audience:'internal',ownerMembershipId:author.membershipId,content},db),submitted=await submitPlanCommand(author,{action:'submit',requestKey:randomUUID(),planId:created.planId,revisionId:created.revisionId,contentDigest:created.contentDigest,expectedAggregateVersion:created.aggregateVersion},db),preview=await createPlanReviewPreview(reviewer,created.planId,{requestKey:randomUUID(),revisionId:created.revisionId,contentDigest:created.contentDigest,expectedAggregateVersion:submitted.aggregateVersion},db),decision=await decidePlan(reviewer,created.planId,{action:'accept',requestKey:randomUUID(),revisionId:created.revisionId,contentDigest:created.contentDigest,expectedAggregateVersion:submitted.aggregateVersion,reviewPreviewId:preview.previewId,rationale:'Explicit synthetic baseline review',deliverySuitabilityConfirmed:true},db);if(!decision.engagementId||!decision.baselineId)throw Error('Reviewed synthetic baseline required');return {author,reviewer,content,created,decision,customerId,engagementId:decision.engagementId,baselineId:decision.baselineId};}
